CREATE TABLE cast_test_source (
    id int,
    bool_val boolean,
    tinyint_val tinyint,
    smallint_val smallint,
    int_val int,
    bigint_val bigint,
    largeint_val largeint,
    float_val float,
    double_val double,
    varchar_val varchar(100),
    decimal256_50_15 decimal(50,15),  
    decimal256_76_20 decimal(76,20),  
    decimal256_76_0 decimal(76,0),    
    decimal_38_10 decimal(38,10),     
    decimal_20_5 decimal(20,5)        
) ENGINE=OLAP
DUPLICATE KEY(id)
DISTRIBUTED BY HASH(id) BUCKETS 1
PROPERTIES (
    "replication_num" = "1"
);
