CREATE TABLE cast_test_target (
    id int,
    target_decimal256 decimal(76,20),
    target_decimal38 decimal(38,10),
    target_int bigint
) ENGINE=OLAP
DUPLICATE KEY(id)
DISTRIBUTED BY HASH(id) BUCKETS 1
PROPERTIES (
    "replication_num" = "1"
);
